import React, {
    forwardRef,
    type HTMLAttributes,
    type MouseEvent,
    type ReactNode,
    useCallback,
} from 'react';
import cn from 'classnames';

import { IconButton, type IconButtonProps } from '@alfalab/core-components-icon-button';
import { getDataTestId } from '@alfalab/core-components-shared';
import {
    StatusBadge,
    type StatusBadgeCustomIcon,
    type StatusBadgeViews,
} from '@alfalab/core-components-status-badge';
import { CrossMIcon } from '@alfalab/icons-glyph/CrossMIcon';

import { useCustomIcons } from './hooks/useCustomIcons';

import defaultColors from './default.module.css';
import commonStyles from './index.module.css';
import invertedColors from './inverted.module.css';

const colorStyles = {
    default: defaultColors,
    inverted: invertedColors,
} as const;

export type BaseToastPlateProps = HTMLAttributes<HTMLDivElement> & {
    /**
     * Дополнительный класс
     */
    className?: string;

    /**
     * Дополнительный класс для заголовка
     */
    titleClassName?: string;

    /**
     * Дополнительный класс для контентной области
     */
    contentClassName?: string;

    /**
     * Дополнительный класс для области с кнопкой действия
     */
    actionSectionClassName?: string;

    /**
     * Дочерние элементы
     */
    children?: ReactNode;

    /**
     * Заголовок компонента
     */
    title?: ReactNode;

    /**
     * Жирный заголовок
     */
    boldTitle?: boolean;

    /**
     * Вид бэйджа
     */
    badge?: StatusBadgeViews;

    /**
     * Слот слева, заменяет стандартную иконку
     */
    leftAddons?: ReactNode;

    /**
     * Кнопка действия
     */
    actionButton?: ReactNode;

    /**
     * Идентификатор для систем автоматизированного тестирования
     */
    dataTestId?: string;

    /**
     * Управляет отображением кнопки закрытия уведомления
     * @deprecated Используйте пропс `closerProps`
     */
    hasCloser?: boolean;

    /**
     * Доп. класс враппера кнопки "закрыть".
     * @deprecated Используйте пропс `closerProps`
     */
    closerWrapperClassName?: string;

    /**
     * Доп. класс кнопки "закрыть".
     * @deprecated Используйте пропс `closerProps`
     */
    closerClassName?: string;

    /**
     * Параметры кнопки закрытия
     * @type {Object}
     * @property {boolean} [hasCloser] - Управляет отображением кнопки закрытия уведомления
     * @property {string} [closerWrapperClassName] - Дополнительный класс враппера кнопки "закрыть"
     * @property {string} [closerClassName] - Дополнительный класс кнопки "закрыть"
     * @property {boolean} [divider] - Показывать разделитель
     * @property {import('@alfalab/core-components-icon-button').IconButtonProps['view']} [view] - Вид кнопки закрытия
     * @default {{ hasCloser: false, closerWrapperClassName: undefined, closerClassName: undefined, divider: true, view: 'primary' }}
     */
    closerProps?: {
        hasCloser?: boolean;
        closerWrapperClassName?: string;
        closerClassName?: string;
        divider?: boolean;
        view?: IconButtonProps['view'];
    };

    /**
     * Растягивает компонент на ширину контейнера
     */
    block?: boolean;

    /**
     * Обработчик клика по крестику
     */
    onClose?: (event?: MouseEvent<HTMLButtonElement>) => void;

    /**
     * Функция, с помощью которой можно переопределить иконки в StatusBadge
     */
    getBadgeIcons?: StatusBadgeCustomIcon;

    /**
     * Набор цветов для компонента
     */
    colors?: 'default' | 'inverted';

    /**
     * Положение кнопки под заголовком компонента
     */
    bottomButtonPosition?: boolean;

    /**
     * Основные стили компонента.
     */
    styles?: { [key: string]: string };
};

export const BaseToastPlate = forwardRef<HTMLDivElement, BaseToastPlateProps>(
    (
        {
            dataTestId,
            className,
            titleClassName,
            contentClassName,
            actionSectionClassName,
            hasCloser: legacyHasCloser,
            leftAddons,
            badge,
            title,
            children,
            actionButton,
            block,
            onClose,
            getBadgeIcons,
            colors = 'default',
            closerWrapperClassName: legacyCloserWrapperClassName,
            closerClassName: legacyCloserClassName,
            bottomButtonPosition = false,
            styles = {},
            closerProps = {
                hasCloser: false,
                closerWrapperClassName: undefined,
                closerClassName: undefined,
                divider: true,
                view: 'primary',
            },
            // not used here
            boldTitle,
            ...restProps
        },
        ref,
    ) => {
        const needRenderLeftAddons = Boolean(leftAddons || badge);
        const { divider, view } = closerProps;
        const hasCloser = legacyHasCloser ?? closerProps.hasCloser;
        const closerWrapperClassName =
            legacyCloserWrapperClassName ?? closerProps.closerWrapperClassName;
        const closerClassName = legacyCloserClassName ?? closerProps.closerClassName;

        const { getCustomIcons } = useCustomIcons();

        const handleClose = useCallback(
            (event: React.MouseEvent<HTMLButtonElement>) => {
                if (onClose) {
                    onClose(event);
                }
            },
            [onClose],
        );

        const customIcons = getCustomIcons(getBadgeIcons);

        return (
            <div
                className={cn(
                    commonStyles.component,
                    colorStyles[colors].component,
                    { [commonStyles.block]: block, [commonStyles.hasCloser]: hasCloser },
                    className,
                )}
                ref={ref}
                data-test-id={getDataTestId(dataTestId, 'component')}
                role='alert'
                aria-live='assertive'
                aria-atomic='true'
                {...restProps}
            >
                <div className={commonStyles.wrapper}>
                    <div className={commonStyles.contentWrapper}>
                        {needRenderLeftAddons && (
                            <div className={commonStyles.leftAddons}>
                                {leftAddons ||
                                    (badge && (
                                        <StatusBadge
                                            view={badge}
                                            dataTestId={getDataTestId(dataTestId, 'badge')}
                                            {...(customIcons && { customIcons })}
                                        />
                                    ))}
                            </div>
                        )}
                        <div
                            className={cn(contentClassName, commonStyles.content, {
                                [commonStyles.hasCloser]: hasCloser,
                                [commonStyles.hasActionButton]: !!actionButton,
                                [commonStyles.direction]: bottomButtonPosition,
                            })}
                        >
                            <div className={commonStyles.contentTitle}>
                                {title && (
                                    <div
                                        className={cn(
                                            titleClassName,
                                            commonStyles.title,
                                            styles.title,
                                        )}
                                    >
                                        {title}
                                    </div>
                                )}
                                {children && (
                                    <div className={commonStyles.children}>{children}</div>
                                )}
                            </div>

                            {actionButton && (
                                <div
                                    className={cn(
                                        actionSectionClassName,
                                        commonStyles.actionSection,
                                        styles.actionSection,
                                        {
                                            [commonStyles.hasCloser]: hasCloser,
                                            [commonStyles.bottomButton]: bottomButtonPosition,
                                        },
                                    )}
                                >
                                    {actionButton}
                                </div>
                            )}
                        </div>
                    </div>
                    {hasCloser && (
                        <div
                            className={cn(
                                commonStyles.closeButtonWrapper,
                                styles.closeButtonWrapper,
                                colorStyles[colors].closeButtonWrapper,
                                closerWrapperClassName,
                                {
                                    [styles.divider]: divider,
                                },
                            )}
                        >
                            <IconButton
                                view={view}
                                icon={CrossMIcon}
                                colors={colors === 'default' ? 'inverted' : 'default'}
                                className={cn(
                                    commonStyles.closeButton,
                                    styles.closeButton,
                                    closerClassName,
                                )}
                                onClick={handleClose}
                                aria-label='закрыть'
                            />
                        </div>
                    )}
                </div>
            </div>
        );
    },
);
