import React from 'react';
import { useIsMounted } from '../useIsMounted/hook.js';

/**
 * Обновление состояния, только если компонент смонтирован
 * Устраняет утечку и варнинги
 */
const useStateIfMounted = (initialValue) => {
    const getIsMounted = useIsMounted();
    const [storedValue, setStoredValue] = React.useState(initialValue);
    const setState = React.useCallback((value) => {
        const isMounted = getIsMounted();
        if (isMounted) {
            setStoredValue(value);
        }
    }, [getIsMounted]);
    return [storedValue, setState];
};

export { useStateIfMounted };
