import { useRef, useEffect, useCallback } from 'react';

/**
 * Хук получения состояния доступности компонента.
 */
const useIsMounted = () => {
    const isMounted = useRef(true);
    useEffect(() => () => {
        isMounted.current = false;
    }, []);
    return useCallback(() => isMounted.current, []);
};

export { useIsMounted };
