import React, {
    type ChangeEvent,
    type DetailedHTMLProps,
    forwardRef,
    type InputHTMLAttributes,
    type LabelHTMLAttributes,
    type ReactNode,
    type Ref,
    type RefObject,
    useRef,
} from 'react';
import mergeRefs from 'react-merge-refs';
import cn from 'classnames';

import { dom, getDataTestId } from '@alfalab/core-components-shared';
import { useFocus } from '@alfalab/hooks';

import { CheckIcon } from './icon';

import defaultColors from './styles/default.module.css';
import styles from './styles/index.module.css';
import invertedColors from './styles/inverted.module.css';

type NativeProps = InputHTMLAttributes<HTMLInputElement>;
type Align = 'start' | 'center';

const colorStyles = {
    default: defaultColors,
    inverted: invertedColors,
};

export type CheckboxProps = Omit<NativeProps, 'size' | 'onChange' | 'enterKeyHint'> & {
    /**
     * Управление состоянием вкл/выкл чекбокса (native prop)
     */
    checked?: boolean;

    /**
     * Обработчик переключения чекбокса
     */
    onChange?: (
        event: ChangeEvent<HTMLInputElement>,
        payload: {
            checked: boolean;
            name?: string;
        },
    ) => void;

    /**
     * Текст подписи к чекбоксу
     */
    label?: ReactNode;

    /**
     * Текст подсказки снизу
     */
    hint?: ReactNode;

    /**
     * Размер компонента
     * @default 20
     */
    size?: 20 | 24;

    /**
     * Компактный текст подписи Только для `size=20`
     * @default false
     */
    compact?: boolean;

    /**
     * Доп. класс чекбокса
     */
    boxClassName?: string;

    /**
     * Доп. класс контента
     */
    contentClassName?: string;

    /**
     * Доп. класс лейбла
     */
    labelClassName?: string;

    /**
     * Доп. класс подсказки
     */
    hintClassName?: string;

    /**
     * Доп. класс ошибки
     */
    errorClassName?: string;

    /**
     * Доп. класс дополнительного слота
     */
    addonsClassName?: string;

    /**
     * Выравнивание
     */
    align?: Align;

    /**
     * Дополнительный слот
     */
    addons?: ReactNode;

    /**
     * Растягивать ли компонент на всю ширину
     */
    block?: boolean;

    /**
     * Управление состоянием включен / выключен
     */
    disabled?: boolean;

    /**
     * Идентификатор для систем автоматизированного тестирования
     */
    dataTestId?: string;

    /**
     * Управление неопределенным состоянием чекбокса
     */
    indeterminate?: boolean;

    /**
     * Отображение ошибки
     */
    error?: ReactNode | boolean;

    /**
     * Положение чекбокса относительно контента
     * @default start
     */
    controlPosition?: 'start' | 'end';

    /**
     * Позиция чекбокса относительно контента
     * @default 'before'
     * @deprecated Используйте prop `controlPosition`
     */
    position?: 'before' | 'after';

    /**
     * Флаг для скрытия нативного инпута.
     * @default false
     */
    hiddenInput?: boolean;

    /**
     * Реф на инпут
     */
    inputRef?: RefObject<HTMLInputElement>;

    /**
     * Пропсы для label
     */
    labelProps?: DetailedHTMLProps<LabelHTMLAttributes<HTMLLabelElement>, HTMLLabelElement>;

    /**
     * Набор цветов для компонента
     * @default default
     */
    colors?: 'default' | 'inverted';
};

export const Checkbox = forwardRef<HTMLLabelElement, CheckboxProps>(
    (
        {
            checked,
            label,
            hint,
            size = 20,
            boxClassName,
            contentClassName,
            labelClassName,
            hintClassName,
            errorClassName,
            addonsClassName,
            controlPosition = 'start',
            position = 'before',
            align = 'start',
            addons,
            block,
            onChange,
            className,
            name,
            disabled,
            dataTestId,
            indeterminate = false,
            hiddenInput = false,
            labelProps,
            error,
            inputRef,
            colors = 'default',
            compact = false,
            ...restProps
        },
        ref,
    ) => {
        const labelRef = useRef<HTMLLabelElement>(null);

        const [focused] = useFocus(labelRef, 'keyboard');

        const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
            if (onChange) {
                onChange(event, { checked: event.target.checked, name });
            }
        };

        const errorMessage = typeof error === 'boolean' ? '' : error;

        const colorStyle = colorStyles[colors];
        const isControlAtEnd =
            (controlPosition ?? (position === 'after' ? 'end' : 'start')) === 'end';

        const renderCheckmark = () => (
            <span className={cn(styles.box, colorStyle.box, boxClassName)}>
                {checked && (
                    <CheckIcon className={cn(styles.checkedIcon, colorStyle.checkedIcon)} />
                )}
                {indeterminate && !checked && (
                    <span className={cn(styles.indeterminateLine, colorStyle.indeterminateLine)} />
                )}
            </span>
        );

        return (
            <label
                {...labelProps}
                className={cn(
                    styles.component,
                    colorStyle.component,
                    styles[`size-${size}`],
                    styles[align],
                    className,
                    labelProps?.className,
                    {
                        [styles.disabled]: disabled,
                        [colorStyle.disabled]: disabled,
                        [styles.checked]: checked,
                        [colorStyle.checked]: checked,
                        [styles.indeterminate]: indeterminate,
                        [colorStyle.indeterminate]: indeterminate,
                        [styles.focused]: focused,
                        [styles.block]: block,
                        [styles['position-after']]: isControlAtEnd,
                        [styles.compact]: compact && size === 20,
                    },
                )}
                ref={mergeRefs([labelRef, ref, labelProps?.ref as Ref<HTMLLabelElement>])}
            >
                {!hiddenInput && (
                    <input
                        type='checkbox'
                        onChange={handleChange}
                        name={name}
                        disabled={disabled}
                        checked={checked}
                        data-test-id={dataTestId}
                        ref={inputRef}
                        {...restProps}
                    />
                )}

                {!isControlAtEnd && renderCheckmark()}

                {(label || hint || errorMessage) && (
                    <span className={cn(styles.content, contentClassName)}>
                        {label && (
                            <span
                                className={cn(styles.label, colorStyle.label, labelClassName)}
                                data-test-id={getDataTestId(dataTestId, 'label')}
                            >
                                {label}
                            </span>
                        )}

                        {hint && !errorMessage && (
                            <span
                                className={cn(styles.hint, colorStyle.hint, hintClassName)}
                                data-test-id={getDataTestId(dataTestId, 'hint')}
                            >
                                {hint}
                            </span>
                        )}

                        {errorMessage && (
                            <span
                                className={cn(styles.errorMessage, errorClassName)}
                                role='alert'
                                data-test-id={getDataTestId(dataTestId, 'error')}
                            >
                                {errorMessage}
                            </span>
                        )}
                    </span>
                )}

                {isControlAtEnd && renderCheckmark()}

                {addons && (
                    // eslint-disable-next-line jsx-a11y/click-events-have-key-events,jsx-a11y/no-static-element-interactions
                    <span
                        className={cn(styles.addons, addonsClassName)}
                        onClick={dom.preventDefault}
                    >
                        {addons}
                    </span>
                )}
            </label>
        );
    },
);

/**
 * Для отображения в сторибуке
 */
Checkbox.defaultProps = {
    indeterminate: false,
};

Checkbox.displayName = 'Checkbox';
