@import '@alfalab/core-components-vars/src/index.css';
@import '../vars.css';

.actionSection {
    align-items: var(--toast-plate-action-align);
}

.title {
    @mixin paragraph_component_primary;
    @mixin row_limit 1;
    word-break: break-all;

    &.boldTitle {
        @mixin accent_component_primary;
    }
}

.closeButtonWrapper {
    &.divider {
        &:before {
            display: var(--toast-plate-action-divider-display);
            position: absolute;
            right: 51px;
            top: var(--gap-12);
            bottom: var(--gap-12);
            width: 1px;
            content: '';
        }
    }
}

.closeButton {
    align-items: var(--toast-plate-close-button-align);
}
